  function bindProjects(){const by=(s,fn)=>{let e=$(s);if(e)e.onclick=fn};document.querySelectorAll('[data-project-select]').forEach(e=>e.onchange=()=>{let id=e.dataset.projectSelect;state.selectedProjects=e.checked?[...new Set([...(state.selectedProjects||[]),id])]:state.selectedProjects.filter(x=>x!==id);persist();render()});document.querySelectorAll('[data-edit-project]').forEach(e=>e.onclick=()=>{state.activeProject=e.dataset.editProject;persist();render()});by('#add-project',()=>{let id='project-'+seed().slice(0,8);state.projects.push({id,name:'새 ABAP 프로젝트',description:'',tables:[],primaryTable:'',fields:[],resultVar:'GT_RESULT',conditionVars:[],source:''});state.activeProject=id;state.selectedProjects=[id];persist();render()});by('#save-project',()=>{let p=state.projects.find(x=>x.id===state.activeProject);if(!p)return;p.name=$('#project-name').value.trim()||'이름 없는 프로젝트';p.description=$('#project-desc').value.trim();p.primaryTable=$('#project-table').value.trim().toUpperCase();p.tables=$('#project-tables').value.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);if(p.primaryTable&&!p.tables.includes(p.primaryTable))p.tables.unshift(p.primaryTable);p.fields=$('#project-fields').value.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);p.resultVar=$('#project-result').value.trim().replace(/^@/,'').toUpperCase()||'GT_DATA';p.conditionVars=$('#project-vars').value.split(',').map(x=>x.trim().replace(/^@/,'').toUpperCase()).filter(Boolean);p.source=$('#project-source').value;persist();toast('프로젝트 설정과 전체 코드를 저장했습니다.');render()});by('#analyze-project',()=>{let src=$('#project-source').value,sel=src.match(/\bSELECT\s+(?:SINGLE\s+|DISTINCT\s+)?([\s\S]*?)\s+FROM\s+([A-Z][A-Z0-9_]+)/i),tables=[...src.matchAll(/\b(?:FROM|JOIN)\s+([A-Z][A-Z0-9_]+)/gi)].map(x=>x[1].toUpperCase()),fields=sel?sel[1].split(',').map(x=>{let m=x.trim().match(/(?:[A-Z0-9_]+~)?([A-Z][A-Z0-9_]*)/i);return m?m[1].toUpperCase():''}).filter(x=>x&&!['SINGLE','DISTINCT'].includes(x)):[],into=(src.match(/\bINTO\s+(?:CORRESPONDING\s+FIELDS\s+OF\s+)?TABLE\s+@?([A-Z][A-Z0-9_]*)/i)||[])[1]||'',vars=[...src.matchAll(/@([A-Z][A-Z0-9_]*)/gi)].map(x=>x[1].toUpperCase()).filter(x=>x!==into&&!['DATA','FINAL'].includes(x));if(sel){$('#project-table').value=sel[2].toUpperCase();$('#project-tables').value=[...new Set(tables)].join(', ');$('#project-fields').value=[...new Set(fields)].join(', ');if(into)$('#project-result').value=into;$('#project-vars').value=[...new Set(vars)].join(', ');toast('SELECT 코드에서 이름을 추출했습니다. 확인 후 저장하세요.')}else toast('SELECT ... FROM 패턴을 찾지 못했습니다. 직접 입력해 주세요.')});by('#delete-project',()=>{if(state.projects.length<=1){toast('마지막 프로젝트는 삭제할 수 없습니다.');return}state.projects=state.projects.filter(x=>x.id!==state.activeProject);state.selectedProjects=(state.selectedProjects||[]).filter(x=>x!==state.activeProject);if(!state.selectedProjects.length)state.selectedProjects=[state.projects[0].id];state.activeProject=state.projects[0].id;persist();render()})}
  function title(v){return ({dashboard:'대시보드',practice:'문제 풀기',sql_lab:'SQL 실습',projects:'프로젝트 코드',wrongbook:'오답노트',schema:'스키마·도움말',settings:'설정'})[v]||'Open SQL Lab'}
